package es.sgcorredores.mobile;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.Manifest;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> files; PermissionRequest pending;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff092c20);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setUserAgentString(web.getSettings().getUserAgentString()+" SGCorredoresAndroid/1.1");web.getSettings().setDomStorageEnabled(true);CookieManager.getInstance().setAcceptCookie(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.getSettings().setCacheMode(WebSettings.LOAD_DEFAULT);getWindow().setNavigationBarColor(0xff092c20);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.setWebViewClient(new WebViewClient(){public void onPageFinished(WebView v,String url){super.onPageFinished(v,url);v.evaluateJavascript("(function(){var s=document.createElement('style');s.textContent='#sgBackBar{display:none!important}';document.head.appendChild(s)})()",null);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&"sg-corredores.github.io".equals(u.getHost()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){}return true;}});
 web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;try{startActivityForResult(p.createIntent(),12);return true;}catch(Exception e){files=null;return false;}}public void onPermissionRequest(PermissionRequest r){runOnUiThread(()->{if(!"https://sg-corredores.github.io".equals(r.getOrigin().toString())){r.deny();return;}pending=r;java.util.ArrayList<String> perms=new java.util.ArrayList<>();for(String x:r.getResources()){if(x.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE))perms.add(Manifest.permission.RECORD_AUDIO);else if(x.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE))perms.add(Manifest.permission.CAMERA);else{r.deny();pending=null;return;}}if(perms.stream().allMatch(p->checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED)){r.grant(r.getResources());pending=null;}else requestPermissions(perms.toArray(new String[0]),13);});}});
 web.loadUrl("https://sg-corredores.github.io/sg-corredores-app/Index.html");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},14);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==13&&pending!=null){boolean ok=g.length>0;for(int x:g)ok&=x==PackageManager.PERMISSION_GRANTED;if(ok)pending.grant(pending.getResources());else pending.deny();pending=null;}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==12&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));files=null;}}
 protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
 public void onBackPressed(){web.evaluateJavascript("(function(){var m=document.getElementById('sgImport');if(m&&m.style.display==='block'){if(confirm('¿Cerrar la importación del pedido?'))m.style.display='none';return true;}var b=document.getElementById('sgBackBtn');if(b&&!b.disabled&&typeof window.sg10Back==='function'){window.sg10Back();return true;}return false;})()",result->{if(!"true".equals(result)){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("¿Salir de SG Corredores?").setNegativeButton("Cancelar",null).setPositiveButton("Salir",(d,w)->finish()).show();}});}
}